#include <stdio.h>

#define MAX_K 10000
#define MAX_M 5005

int T[MAX_M];
int A[MAX_K + 1];

int main(void) {
    long long N;
    int M;

    if (scanf("%lld", &N) != 1) return 0;
    if (scanf("%d", &M) != 1) return 0;

    for (int i = 1; i <= M; i++) {
        scanf("%d", &T[i]);
    }

    long long current_len = N;
    for (int i = 1; i <= M; i++) {
        current_len -= current_len / T[i];
    }

    int K = current_len < MAX_K ? (int)current_len : MAX_K;

    for (int i = 1; i <= K; i++) {
        A[i] = i;
    }

    for (int i = M; i >= 1; i--) {
        int t = T[i] - 1;
        for (int j = 1; j <= K; j++) {
            A[j] += (A[j] - 1) / t;
        }
    }

    for (int i = 1; i <= K; i++) {
        printf("%d\n", A[i]);
    }

    return 0;
}
